-- ============================================================
-- 5. EVENT_PHASES (3 per event = 45)
-- ============================================================
insert into public.event_phases (event_id, name, ord, pay_rate, starts_at, ends_at)
select e.id, p.name, p.ord, p.pay_rate,
       case when p.ord=1 then e.starts_at - interval '4 hours'
            when p.ord=2 then e.starts_at
            else coalesce(e.ends_at, e.starts_at + interval '6 hours')
       end as starts_at,
       case when p.ord=1 then e.starts_at
            when p.ord=2 then coalesce(e.ends_at, e.starts_at + interval '6 hours')
            else coalesce(e.ends_at, e.starts_at + interval '6 hours') + interval '3 hours'
       end as ends_at
from public.events e
cross join (values
  ('Ingress',      1::int,  800.00),
  ('Event Proper', 2::int, 1500.00),
  ('Egress',       3::int,  600.00)
) as p(name, ord, pay_rate)
where e.id::text like 'd0000000-0000-0000-0000-%'
on conflict (event_id, ord) do nothing;

