-- ============================================================
-- 10. PLACEHOLDER IMAGES (so the admin UI renders something visible
-- without uploading real bytes to Supabase Storage). The admin's storage
-- helpers pass `http(s)://` paths through unchanged.
--
--   * Photo: i.pravatar.cc — varies by employee_code seed
--   * QR:    api.qrserver.com — generates a real scannable QR encoding
--           the employee uuid (so the mobile scan flow even works against
--           seeded employees)
-- ============================================================
update public.employees
set photo_url = 'https://i.pravatar.cc/300?u=' || employee_code,
    qr_badge_url = 'https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=' || id::text,
    updated_at = (now() at time zone 'utc')
where id::text like 'c0000000-0000-0000-0000-%';

-- BADGES (30 — one per employee, all active, pointing at the placeholder URL)
insert into public.badges (employee_id, storage_path, status)
select id,
       'https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=' || id::text,
       'active'
from public.employees
where id::text like 'c0000000-0000-0000-0000-%'
on conflict (employee_id) do nothing;
